import re,os
decls=[]
for root,d,fs in os.walk('AlgebraicJacobian'):
    for f in sorted(fs):
        if not f.endswith('.lean'): continue
        p=os.path.join(root,f)
        s=open(p).read()
        lines=s.split('\n')
        # find declaration starts
        starts=[(i,l) for i,l in enumerate(lines) if re.match(r'^\s*(noncomputable\s+)?(private\s+)?(def|theorem|lemma|instance|abbrev|structure)\s', l)]
        for idx,(i,l) in enumerate(starts):
            end = starts[idx+1][0] if idx+1<len(starts) else len(lines)
            body='\n'.join(lines[i:end])
            # header = up to ':=' or 'where'
            m=re.search(r':=|\bwhere\b', body)
            hdr = body[:m.start()] if m else body
            if re.search(r'rep\s*:\s*\(divFunctor', hdr):
                name=re.match(r'^\s*(?:noncomputable\s+)?(?:private\s+)?(?:def|theorem|lemma|instance|abbrev|structure)\s+(\S+)', l)
                decls.append((p,i+1,name.group(1) if name else '?'))
print("declarations taking an explicit rep : (divFunctor ...) binder:", len(decls))
